"""
config_precedence_merge.py

Implements merge_settings(defaults, file_config, env) -> dict
Implements redact_secrets(config: dict) -> dict

Precedence: defaults < file_config < environment variables (APP__ prefix).
"""

import copy


# Keys whose values should be redacted
_SENSITIVE_KEYS = {"password", "token", "secret", "api_key"}


def _parse_bool(value: str):
    """Return bool if value is 'true'/'false', else None."""
    lower = value.lower()
    if lower == "true":
        return True
    if lower == "false":
        return False
    return None


def _parse_int(value: str):
    """Return int if value is a base-10 integer string, else None."""
    try:
        return int(value, 10)
    except ValueError:
        return None


def _parse_list(value: str):
    """Return list of trimmed non-empty strings if value contains a comma, else None."""
    if "," in value:
        return [p.strip() for p in value.split(",") if p.strip()]
    return None


def _parse_value(value: str):
    """Parse a string value into bool, int, list, or str."""
    result = _parse_bool(value)
    if result is not None:
        return result

    result = _parse_int(value)
    if result is not None:
        return result

    result = _parse_list(value)
    if result is not None:
        return result

    return value


def _deep_merge(base: dict, override: dict) -> dict:
    """
    Deep-merge two dictionaries. Values in override take precedence.
    Dictionaries are merged recursively; other types are replaced.
    Neither input is mutated.
    """
    result = copy.deepcopy(base)
    for key, val in override.items():
        if key in result and isinstance(result[key], dict) and isinstance(val, dict):
            result[key] = _deep_merge(result[key], val)
        else:
            result[key] = copy.deepcopy(val)
    return result


def _set_nested(d: dict, keys: list, value):
    """
    Set a value in a nested dict structure given a list of keys.
    Intermediate dicts are created as needed.
    """
    for key in keys[:-1]:
        if key not in d or not isinstance(d[key], dict):
            d[key] = {}
        d = d[key]
    d[keys[-1]] = value


def _parse_env_var(key: str, value: str, prefix: str):
    """
    Parse a single environment variable into (segments, parsed_value).
    Returns None if the key does not start with prefix or yields no segments.
    """
    if not key.startswith(prefix):
        return None
    remainder = key[len(prefix):]
    segments = [seg.lower() for seg in remainder.split("__") if seg]
    if not segments:
        return None
    return segments, _parse_value(value)


def _env_to_dict(env: dict) -> dict:
    """
    Parse environment variables with APP__ prefix into a nested dict.
    """
    result = {}
    prefix = "APP__"
    for key, value in env.items():
        parsed = _parse_env_var(key, value, prefix)
        if parsed is None:
            continue
        segments, parsed_value = parsed
        _set_nested(result, segments, parsed_value)
    return result


def merge_settings(defaults: dict, file_config: dict, env: dict) -> dict:
    """
    Merge settings with precedence: defaults < file_config < env vars.

    Args:
        defaults: Base default settings dictionary.
        file_config: Settings loaded from a configuration file.
        env: Environment variables (dict[str, str]).

    Returns:
        A new merged settings dictionary. Input dicts are never mutated.
    """
    result = copy.deepcopy(defaults)
    result = _deep_merge(result, file_config)
    env_dict = _env_to_dict(env)
    result = _deep_merge(result, env_dict)
    return result


def redact_secrets(config: dict) -> dict:
    """
    Return a deep copy of config where any key named 'password', 'token',
    'secret', or 'api_key' (at any nesting level) has its value replaced
    with '<redacted>'. The input dict is never mutated.

    Args:
        config: A settings dictionary, possibly nested.

    Returns:
        A new dictionary with sensitive values redacted.
    """
    result = {}
    for key, value in config.items():
        if key in _SENSITIVE_KEYS:
            result[key] = "<redacted>"
        elif isinstance(value, dict):
            result[key] = redact_secrets(value)
        else:
            result[key] = copy.deepcopy(value)
    return result

